(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["id"] = {"ui":{"skip":"Langsung ke isi","back":"← Kembali ke AI-gile","lang.button":"Bahasa: {name}","lang.dialog":"Pilih bahasa","lang.search":"Cari bahasa","lang.none":"Tidak ada bahasa yang cocok","lang.notYet":"{name} belum diterjemahkan","theme.aria":"Ganti antara tema terang dan gelap","theme.toLight":"Ganti ke tema terang","theme.toDark":"Ganti ke tema gelap","index.title":"AI-gile: tim dev AI-mu, dalam satu papan","index.description":"AI-gile adalah papan kanban untuk tim pemrograman AI. Mereka bekerja saat kamu tidur; kamu cukup mengurus satu tumpukan pendek: hal yang perlu diputuskan, dites, dan disetujui.","hero.logoAlt":"Ikon papan AI-gile","hero.h1.html":"Tim dev AI-mu, dalam satu&nbsp;papan.","hero.alpha":"🐣 Pra-alfa tertutup","hero.alphaTitle":"Masih awal dan belum selesai: terima kasih sudah mau mencoba!","hero.lede":"Mereka membangun selagi kamu tidur. Kamu bangun dan menemukan satu tumpukan pendek: beberapa pertanyaan, beberapa hal untuk dites, satu atau dua berlian ungu. Klik, setujui, lanjut ngopi.","dl.windows":"Aplikasi Windows","dl.browser":"Jalankan di browser","dl.soon":"Segera hadir","dl.notify":"🔔 Kabari aku saat dibuka","dl.notifySmall":"Alfa atau beta","hero.secondary":"Agile, tapi timnya tidak butuh kopi stand-up. (Stand-up tetap jalan, sih.)","pitch.h2":"AI-gile dalam sebanyak kata yang kamu mau","pitch.lede":"Pilih panjangnya, dari satu kata sampai 144. Setiap panjang punya deskripsinya sendiri, ditulis khusus untuk ukuran itu. Geser slider atau pakai tombol panah.","pitch.rangeLabel":"Panjang dalam kata","pitch.dice":"🎲 versi lain","pitch.words.one":"{n} kata","pitch.words.other":"{n} kata","pitch.letters.one":"{n} huruf","pitch.letters.other":"{n} huruf","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} kartu di papan sekarang","count.line.html.other":"{n} kartu di papan sekarang","features.aria":"Apa yang dilakukannya","f.pile.h":"Satu tumpukan untukmu","f.pile.html":"<b>Untukmu</b> berisi semua yang menunggumu, dari semua proyek: pertanyaan, hal untuk dites, tugas yang hanya bisa dikerjakan manusia. Antreanmu memberi tahu apa yang berikutnya dan berapa lama.","f.sleep.h":"Tim yang bekerja saat kamu tidur","f.sleep.p":"Setiap proyek punya lead dan tim agen AI. Beri komentar di sebuah kartu, tim pun bangun, mengerjakannya, lalu mengembalikannya dengan langkah-langkah yang bisa diikuti manusia yang sedang capek.","f.tester.h":"Penguji AI memeriksa lebih dulu","f.tester.p":"Sebelum sampai ke kamu, penguji mengikuti langkah-langkahnya di salinan aplikasi dan menunjukkan apa yang dilihatnya, lengkap dengan tangkapan layar. Telusuri yang lolos dan setujui dengan satu klik.","f.proof.h":"Bukti, bukan janji","f.proof.p":"Setiap serah terima menunjukkan apa yang berubah: berkas, diff, tangkapan layar. Tidak perlu membuka satu per satu aplikasi untuk tahu sudah selesai atau belum.","f.chat.h":"Ngobrol dengan lead-mu","f.chat.p":"Bilah ala Discord: satu ikon per proyek, berlian ungu untuk yang butuh kamu. Kirim ide ke lead; ia mengubahnya jadi kartu dan rencana, dengan tombol ✅ Go.","f.tidy.h":"Rapi dengan sendirinya","f.tidy.p":"Kartu yang berkaitan digabung jadi satu, judul yang berantakan dibereskan, dan pemeriksaan token menjaga kode tetap ramping. Lebih sedikit yang harus dipindah-pindah, lebih sedikit yang harus dipikirkan.","f.private.h":"Milikmu, di komputermu","f.private.li1":"Papan berjalan di mesinmu sendiri dan hanya menjawab kamu.","f.private.li2":"Pesan pribadi antarmanusia dienkripsi ujung ke ujung.","f.private.li3":"Tanpa akun, tanpa pelacak, tanpa cookie.","f.lang.h":"Dalam bahasamu","f.lang.p":"Lebih dari 120 bahasa, dari Belanda, Wales, dan Jepang sampai bajak laut, Yoda, dan Klingon, dengan tombol cepat kembali ke bahasa Inggris untuk istilah pengembang.","tl.aria":"Lini masa dari percakapan pertama sampai peta jalan","tl.h2":"Dari obrolan pertama sampai yang berikutnya","tl.lede":"Tanggal dan jam sungguhan, dalam zona waktumu sendiri. Setelah hari ini, itu baru rencana, tanpa janji tanggal.","tl.today":"Hari ini","tl.planned":"direncanakan","tl.cards.one":"{n} kartu","tl.cards.other":"{n} kartu","join.h2":"Ikut serta","join.lede":"AI-gile dibuat oleh satu manusia kecil dan banyak agen yang sabar. Untuk sekarang masih privat, alfa tertutup bersama teman-teman. Mau ikut coba saat dibuka?","join.btn":"Daftarkan minat","join.small":"Kami kirim email, tidak lebih","footer.tag":"AI-gile. Tanpa pelacak, tanpa cookie, tanpa kopi stand-up.","footer.licence":"Lisensi bisnis","footer.status":"Status","form.sending":"Mengirim…","form.failed":"Belum berhasil: coba lagi nanti.","form.offline":"AI-gile tidak terjangkau: coba lagi nanti.","interest.title":"AI-gile: kabari aku saat alfa dibuka","interest.description":"Tinggalkan emailmu untuk tahu kapan alfa atau beta tertutup AI-gile dibuka.","interest.h1":"🔔 Kabari aku saat dibuka","interest.lede":"AI-gile masih dalam pra-alfa tertutup. Tinggalkan emailmu dan kami akan menulis sekali, saat ada tempat untukmu.","interest.email":"Emailmu","interest.which":"Tes yang mana?","interest.alpha":"Alfa tertutup: awal, kasar, banyak perubahan","interest.beta":"Beta: lebih stabil, nanti","interest.both":"Salah satu, mana yang duluan","interest.submit":"Masukkan aku ke daftar","interest.thanks":"Terima kasih! Kamu sudah ada di daftar.","interest.kept":"Hanya emailmu dan tes pilihanmu yang disimpan, khusus untuk daftar ini. Tanpa newsletter, tanpa pelacak.","licence.title":"AI-gile: lisensi bisnis","licence.description":"Memakai AI-gile untuk bisnismu? Ajukan lisensi bisnis gratis.","licence.h1":"📜 Lisensi bisnis","licence.lede":"Memakai AI-gile di tempat kerja? Ceritakan siapa kamu dan apa yang kamu kerjakan. Kalau bermanfaat, lisensinya gratis.","licence.company":"Perusahaan","licence.website":"Situs web","licence.what":"Bidang usahamu","licence.how":"Bagaimana ini membantu dunia","licence.email":"Email","licence.submit":"Ajukan","licence.thanks":"Terima kasih! Kami akan membalas lewat email.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Semua tenang","status.checking":"Memeriksa…","status.offline":"Layanan status belum terjangkau (mencoba lagi)","status.updated":"diperbarui {ago}","status.justNow":"baru saja","status.min":"{n} menit lalu","status.hours":"{n} jam lalu","status.days":"{n} hari lalu","live.h2":"Lihat proses pembuatannya, langsung","live.caption":"Setiap kartu disembunyikan: Anda melihat bentuk pekerjaannya, bukan kata-katanya.","live.watching.one":"langsung: {n} menonton","live.watching.other":"langsung: {n} menonton","live.offline":"Papan langsung sedang istirahat sebentar. Cek lagi nanti ya.","live.cols":"Backlog|Akan dikerjakan|Dikerjakan|Tim memeriksa|Giliranmu tes|Untuk tim|Selesai","live.last.now":"Kartu terakhir dipindahkan baru saja","live.last.min.one":"Kartu terakhir dipindahkan {n} menit lalu","live.last.min.other":"Kartu terakhir dipindahkan {n} menit lalu","live.last.hour.one":"Kartu terakhir dipindahkan {n} jam lalu","live.last.hour.other":"Kartu terakhir dipindahkan {n} jam lalu","live.last.day.one":"Kartu terakhir dipindahkan {n} hari lalu","live.last.day.other":"Kartu terakhir dipindahkan {n} hari lalu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Didelegasikan."]},{"n":2,"texts":["Kanban robot.","Agen, tertata.","Ide, jadi."]},{"n":3,"texts":["Kanban untuk robot.","Ide jadi fitur.","Kanban agen gratis."]},{"n":5,"texts":["Papan kanban yang dijalankan agen.","Kamu menulis kartu. Agen membangun.","Gratis, lokal, teruji, agak konyol."]},{"n":8,"texts":["Papan kanban gratis tempat agen AI bekerja.","Tulis ide. Agen membangunnya. Kamu menyetujui.","Agile untuk satu manusia dan banyak robot sabar."]},{"n":13,"texts":["Papan kanban di komputermu, tempat agen AI mengambil kartu, mengerjakannya, lalu mengembalikannya padamu.","Tulis sebuah ide. Tim agen membangunnya, lalu seorang penguji memeriksanya sebelum sampai ke kamu.","Gratis, tanpa akun, tanpa pelacak: satu papan, beberapa robot, dan kamu yang memegang kendali."]},{"n":21,"texts":["AI-gile adalah papan kanban untuk bekerja bersama agen pemrograman AI. Mereka mengambil kartunya; kamu yang mengetes dan menyetujuinya.","Setiap proyek punya seorang lead dan tim agen AI. Beri komentar di kartu mana pun, dan tim langsung bekerja.","Papan tugas pribadi yang gratis dan berjalan di komputermu sendiri. Pekerjanya robot. Yang berkata ya adalah kamu."]},{"n":34,"texts":["Kamu menaruh ide di sebuah papan. Tim agen AI mengubahnya jadi fitur yang berfungsi, mengetesnya, lalu menyerahkannya kembali dengan langkah-langkah untuk dicoba. Tidak ada yang dianggap selesai sebelum kamu bilang begitu.","AI-gile adalah papan kanban buatan sendiri yang dibuat Rich dengan banyak bantuan dari agen-agen yang kini diurusnya. Gratis, berjalan di komputermu, dan dibagikan ke teman-teman, bukan dijual.","Bayangkan papan kanban biasa, dengan kolom dari Backlog sampai Selesai, hanya saja kartunya diambil oleh agen AI. Mereka melaporkan kemajuan, bertanya saat buntu, dan selalu menunggu acungan jempolmu."]},{"n":55,"texts":["AI-gile adalah papan kanban yang timnya terdiri dari agen AI. Setiap proyek punya lead yang merencanakan pekerjaan dan pembantu yang membangunnya. Saat sebuah fitur siap, penguji AI mencobanya dan mengambil tangkapan layar, lalu fitur itu mendarat di tumpukanmu. Setujui, atau beri komentar dan mereka mengerjakannya ulang.","Awalnya ini cara satu orang melacak banyak sesi pemrograman AI sekaligus, lalu tumbuh jadi papan sungguhan. Ia berjalan di mesinmu, tanpa akun, tanpa pelacak. Gratis untuk teman dan siapa pun yang penasaran. Ia juga belum selesai, jadi harap maklum kalau ada sisi kasar dan kejutan kecil.","Ini versi jujurnya. Kamu tetap harus punya ide, dan tetap harus memeriksa hasilnya. Yang dikerjakan AI-gile adalah semua yang ada di antaranya: menjaga kartu tetap urut, membangunkan agen yang tepat saat kamu berkomentar, menunjukkan persis apa yang berubah, dan menyimpan semuanya dalam satu tumpukan pendek untukmu."]},{"n":89,"texts":["AI-gile adalah papan kanban gratis yang kamu jalankan di komputermu sendiri. Alih-alih orang, setiap proyek punya tim agen AI: seorang lead yang mengubah ide-idemu jadi kartu dan rencana, dan pembantu yang mengambil kartu sesuai urutan prioritas. Setelah sesuatu selesai dibangun, penguji AI mengikuti langkah tesnya dan menunjukkan apa yang dilihatnya. Lalu hasilnya menunggu di satu tumpukan bernama Untukmu. Kamu menyetujuinya, atau memberi komentar dan tim mencoba sekali lagi. Tidak ada yang sampai ke Selesai tanpa kamu.","Beberapa fitur yang mungkin tak kamu duga. Penjaga malam mengisi kolom Akan dikerjakan selagi kamu tidur, dengan memilih kartu yang tidak butuh jawabanmu. Penghitung token menunjukkan berapa banyak yang dipakai agen hari ini dan minggu ini, dan Mode Tanpa Token menyuruh mereka berhenti menghabiskan. Kamu bisa berkirim pesan dengan teman, dan pesan pribadi dienkripsi ujung ke ujung. Papan ini berbahasa sekitar 120 bahasa, termasuk Belanda, Flemish, bajak laut, dan Klingon. Semuanya tanpa biaya sepeser pun, dan tak ada yang berusaha menjualnya padamu.","AI-gile adalah proyek kecil pribadi, bukan perusahaan. Rich ingin mengurus beberapa proyek pemrograman AI tanpa membuka tiap aplikasi untuk mengeceknya, jadi ia dan para agen membuat papan untuk itu, lalu memakai papan itu untuk membangun sisanya. Statusnya pra-alfa tertutup, artinya ia berfungsi, kurang lebih, untuk segelintir teman. Tidak ada halaman harga, tidak ada newsletter, dan tidak ada rencana pertumbuhan. Kalau kedengarannya berguna, kamu bisa minta mencobanya saat dibuka sedikit lebih lebar."]},{"n":144,"texts":["AI-gile adalah papan kanban untuk satu manusia dan banyak agen AI. Ia berjalan di komputermu sendiri dan sepenuhnya gratis. Kamu menambahkan proyek, dan setiap proyek mendapat lead beserta tim kecil. Kamu ngobrol dengan lead, agak mirip Discord, dan menjelaskan sebuah ide; lead mengubahnya jadi kartu dan rencana, lalu menunggu kamu menekan Go. Tim mengerjakan kartu sesuai urutan prioritas, memakai antarmuka baris perintah sederhana yang dibuat untuk model bahasa. Sebelum apa pun kembali kepadamu, penguji AI mengikuti langkah-langkahnya di salinan aplikasi dan melampirkan tangkapan layar. Pekerjaan yang selesai mendarat di tumpukanmu bersama berkas yang berubah dan diff-nya. Kamu menyetujuinya, atau meninggalkan komentar, lalu tim bangun dan mencoba lagi. Hanya kamu yang bisa memindahkan kartu ke Selesai.","Kira-kira begini sehari bersama AI-gile. Malam hari kamu meninggalkan beberapa komentar: tombol ini salah tempat, daftar itu harus diurutkan, bisakah ada mode gelap. Kamu pergi tidur. Para agen membaca komentarnya, membuat perubahan, mengetesnya, dan menyerahkannya kembali padamu. Kalau kolom Akan dikerjakan kosong, penjaga malam mengisinya dari backlog dengan kartu yang tidak butuh jawabanmu. Pagi harinya ada satu tumpukan pendek: beberapa pertanyaan dan beberapa hal untuk dicoba, masing-masing dengan langkah yang bisa diikuti orang mengantuk dan tangkapan layar yang membuktikannya berfungsi. Kamu menelusurinya, menyetujui yang bagus dan mengembalikan sisanya. Penghitung token menunjukkan pemakaiannya, dan Mode Tanpa Token siap untuk minggu-minggu hemat. Kalau ada yang kurang pas, tinggal komentar lagi dan siklusnya berulang. Lalu kamu sarapan, hal yang belum bisa dibantu para agen.","Pertama, apa yang bukan AI-gile. Ia bukan startup, tidak dijual, dan tak seorang pun mengumpulkan datamu. Ia papan gratis yang berjalan di komputermu, tanpa akun, tanpa pelacak, dan tanpa cookie. Yang ia adalah: satu tempat rapi untuk melihat semua proyek pemrograman AI sekaligus, dengan tim agen yang mengerjakan kartu dan kamu yang mengambil keputusan. Ia menggabungkan kartu yang berkaitan, membereskan judul yang berantakan, dan menjaga agar kodenya tetap ramping. Ia berbicara sekitar 120 bahasa, dari Belanda dan Flemish sampai bajak laut dan Klingon. Teman-teman bisa saling berkirim pesan, secara pribadi dan terenkripsi. Ia dibuat oleh Rich dan banyak agen yang sabar, kebanyakan dengan memakai dirinya sendiri. Statusnya pra-alfa tertutup, jadi di beberapa bagian masih kasar. Kalau kedengarannya seru, mintalah baik-baik dan kamu mungkin bisa masuk lebih awal."]}],"quips":{"1":"Satu kata. Berani. Mungkin terlalu berani.","3":"Tiga kata. Sudah lebih jujur daripada kebanyakan halaman produk.","8":"Delapan kata. Masih lebih pendek daripada satu stand-up.","21":"Panjangnya itu story point, omong-omong. Ya iyalah.","55":"Lima puluh lima kata. Dua kartu selesai selagi kamu membaca ini.","144":"Itu yang terpanjang. Tidak ada 233. Para agen sudah tidur."}},"timeline":{"first-idea.name":"Ide pertama","first-idea.line":"Percakapan pertama, sebelum ada satu baris kode pun.","first-board.name":"Papan pertama","first-board.line":"Papan yang melacak pembuatannya sendiri: kartu, kolom, seret dan lepas, proyek.","team-roles.name":"Tim dan peran","team-roles.line":"Profil agen, templat tim, ruang, dan siapa mengerjakan apa.","install.name":"Pemasangan dan rilis","install.line":"Satu zip yang bisa dipasang teman, pembaruan otomatis, kanal, dan kembali ke versi lama.","usage-saver.name":"Penghemat pemakaian","usage-saver.line":"Ukur biaya tiap proses, jaga kode tetap ramping, hemat batasmu.","friends.name":"Teman dan berbagi","friends.line":"Pesan pribadi, relai teracak, undangan, peran, dan proyek bersama.","languages.name":"Bahasa","languages.line":"Setiap teks layar dalam berkas bahasa, dimulai dari Belanda dan Flemish.","ai-tester.name":"Penguji AI","ai-tester.line":"Penguji memeriksa setiap serah terima lebih dulu dan menunjukkan apa yang dilihatnya.","website.name":"Situs web","website.line":"aigile.lol, teaser, dan lini masa ini.","streaming.name":"Obrolan dan streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF, dan emoji.","no-ai.name":"Edisi Tanpa AI","no-ai.line":"Papan untuk orang yang menulis kode tanpa AI, dan papan publik.","night-watch.name":"Penjaga malam","night-watch.line":"Seorang penjaga dan Scrum Master menjaga tim tetap fokus selagi kamu tidur.","p-more.name":"Yang lainnya","p-more.line":"Ide-ide kecil yang masih menunggu giliran.","p-android.name":"Ponsel dan Android","p-android.line":"Buka papanmu dari ponsel, lalu aplikasi Android asli.","p-release.name":"Alfa dan seterusnya","p-release.line":"Alfa tertutup, situs langsung, lalu beta.","p-languages.name":"Lebih banyak bahasa","p-languages.line":"Lebih dari seratus bahasa, dan mode imersi untuk pembelajar.","p-engines.name":"Lebih banyak mesin AI","p-engines.line":"Pilih Claude, Codex, atau Gemini untuk tiap agen.","p-pro.name":"Praktik profesional","p-pro.line":"Label risiko, gerbang merge, kartu insiden, dan pagar pengaman.","p-self.name":"Menjagamu","p-self.line":"Mode lelah, pengingat merawat diri, dan 4:20.","p-servers.name":"Server dan skala","p-servers.line":"Pengaturan server global, peran, dan perencanaan untuk berkembang.","p-livestream.name":"Tambahan streaming","p-livestream.line":"Obrolan Twitch, emoji kustom, dan tampilan langsung publik."}};
